1	/* Wishweave Wonders — Level 1 UI.
2	   The HUD reproduces the approved cream stitched pills (assets/ui/pill.webp as a 9-slice border image),
3	   brown text, coral PURL / teal LOOP labels with gold flower icons, the round stitched pause button and the
4	   WISHWEAVE WONDERS logo. Geometry follows the approved 841-px design, scaled by --k (CSS px per design px,
5	   set by main.js from the game width) with legibility minimums, and reflows on short screens. */
6	
7	:root {
8	  --brown: #552916;
9	  --brown-2: #603319;
10	  --coral: #c51640;
11	  --coral-bright: #f24c7d;
12	  --teal: #067e8d;
13	  --teal-bright: #03a7ae;
14	  --teal-deep: #007685;
15	  --cream: #fff8e8;
16	  --cream-2: #f8e6ca;
17	  --stitch: #d6a24a;
18	  --gold: #f2b83a;
19	  --grey: #aaa398;
20	  --k: 0.49;
21	  --hud-font: max(11px, calc(var(--k) * 24px));
22	  --gap: max(3px, calc(var(--k) * 9px));
23	  --edge: max(6px, calc(var(--k) * 16px));
24	  --rw-h: max(34px, calc(var(--k) * 73px));
25	  --rw-bottom: max(8px, calc(var(--k) * 46px));
26	  color-scheme: light;
27	}
28	
29	* { box-sizing: border-box; }
30	
31	html, body {
32	  margin: 0; height: 100%; overflow: hidden;
33	  background: #2b1810;
34	  font-family: "Nunito", "Baloo 2", "Trebuchet MS", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
35	  font-synthesis: none;
36	  -webkit-text-size-adjust: 100%;
37	  text-size-adjust: 100%;
38	  overscroll-behavior: none;
39	}
40	
41	button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; }
42	
43	[hidden] { display: none !important; }
44	
45	/* #app is the safe content rectangle: the viewport minus env(safe-area-inset-*). Inside the Android host the
46	   WebView is already padded by the system-bar/cutout insets, so env() reads 0 there and nothing is counted twice. */
47	#app {
48	  position: fixed; inset: 0;
49	  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px)
50	           env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
51	  display: flex; align-items: center; justify-content: center;
52	  background:
53	    radial-gradient(ellipse at 50% 30%, rgba(255, 196, 120, .16), rgba(0, 0, 0, 0) 60%),
54	    repeating-linear-gradient(45deg, rgba(255, 230, 190, .035) 0 6px, rgba(0, 0, 0, 0) 6px 12px),
55	    linear-gradient(180deg, #4a2a1a, #23130c);
56	}
57	
58	/* The play area. main.js sizes it: full safe width on phones, a centred portrait column on wide screens. */
59	#game {
60	  position: relative;
61	  width: 100%; height: 100%;
62	  overflow: hidden;
63	  background: #1d120c;
64	  touch-action: none;
65	  user-select: none; -webkit-user-select: none;
66	  -webkit-touch-callout: none;
67	  -webkit-tap-highlight-color: transparent;
68	  contain: layout paint;
69	}
70	#game.is-column { box-shadow: 0 0 0 1px rgba(255, 226, 170, .18), 0 0 40px rgba(0, 0, 0, .55); }
71	
72	#view { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
73	
74	/* ---------- Stitched cream pill (9-slice of assets/ui/pill.webp, 798×193, caps ≈ 96 px) ---------- */
75	.pill {
76	  --ph: 2.05em;
77	  display: inline-flex; align-items: center; justify-content: center;
78	  height: var(--ph);
79	  padding: 0 1.15em;
80	  border: 0 solid transparent;
81	  border-image-source: url("assets/ui/pill.webp");
82	  border-image-slice: 96 100 fill;
83	  border-image-width: calc(var(--ph) / 2) calc(var(--ph) * .53);
84	  border-image-repeat: stretch;
85	  color: var(--brown);
86	  font-weight: 800;
87	  letter-spacing: .02em;
88	  white-space: nowrap;
89	  line-height: 1;
90	  filter: drop-shadow(0 .1em .16em rgba(75, 35, 28, .38));
91	  margin: 0;
92	}
93	
94	/* ---------- HUD ---------- */
95	.hud {
96	  position: absolute; left: 0; right: 0; top: 0;
97	  padding-top: max(5px, calc(var(--k) * 14px));
98	  display: flex; flex-direction: column; align-items: center;
99	  gap: var(--gap);
100	  font-size: var(--hud-font);
101	  pointer-events: none;
102	  z-index: 10;
103	}
104	.hud-logo {
105	  display: block;
106	  width: calc(var(--k) * 404px); height: auto; aspect-ratio: 855 / 306;
107	  margin-bottom: calc(var(--k) * -4px);
108	  filter: drop-shadow(0 calc(var(--k) * 5px) calc(var(--k) * 7px) rgba(60, 25, 10, .45));
109	  pointer-events: none;
110	}
111	#game.no-logo .hud-logo { display: none; }
112	
113	.hud-phase { min-width: max(7.6em, calc(var(--k) * 210px)); padding: 0 1.3em; }
114	
115	.hud-counts { display: flex; gap: max(6px, calc(var(--k) * 18px)); }
116	.hud-count {
117	  min-width: max(8.4em, calc(var(--k) * 220px));
118	  justify-content: flex-start;
119	  gap: .42em;
120	  padding: 0 .95em 0 .55em;
121	  transform-origin: 50% 50%;
122	}
123	.hud-count .flower { width: 1.42em; height: 1.42em; flex: none; margin: -.2em 0; filter: drop-shadow(0 .05em .05em rgba(90, 45, 10, .4)); }
124	.hud-count .who { font-size: .93em; letter-spacing: .03em; }
125	.hud-count.purl .who { color: var(--coral); }
126	.hud-count.loop .who { color: var(--teal); }
127	.hud-count .num { margin-left: auto; padding-left: .5em; font-variant-numeric: tabular-nums; }
128	.hud-count .num b { font-weight: 800; }
129	.hud-count.up { animation: pop .55s cubic-bezier(.2, 1.6, .4, 1); }
130	.hud-count.down { animation: shake .5s ease-in-out; }
131	.hud-count.down .num { color: #b52248; transition: color .2s; }
132	@keyframes pop { 0% { transform: scale(1); } 35% { transform: scale(1.16); filter: drop-shadow(0 0 .5em rgba(255, 210, 90, .95)); } 100% { transform: scale(1); } }
133	@keyframes shake { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-.35em) rotate(-2deg); } 40% { transform: translateX(.3em) rotate(2deg); } 60% { transform: translateX(-.22em); } 80% { transform: translateX(.12em); } }
134	
135	.hud-objective {
136	  position: relative;
137	  font-size: max(10.5px, calc(var(--k) * 22px));
138	  min-width: max(15.5em, calc(var(--k) * 354px));
139	  max-width: calc(100% - 2 * var(--edge));
140	  padding: 0 2.6em 0 2.2em;
141	}
142	.hud-objective .txt { overflow: hidden; text-overflow: ellipsis; }
143	.hud-objective .flag { position: absolute; right: .95em; top: 50%; width: 1.5em; height: 1.5em; transform: translateY(-52%); }
144	.hud-objective.is-message .txt { animation: msgIn .35s ease-out; }
145	.hud-objective.kind-hit .txt { color: #8e1d35; }
146	@keyframes msgIn { from { transform: scale(.85); opacity: .2; } to { transform: scale(1); opacity: 1; } }
147	
148	/* Slim race-progress thread: coral bead = Purl, teal bead = Loop (computer rival). */
149	.race-thread {
150	  position: relative;
151	  width: max(190px, calc(var(--k) * 440px));
152	  height: 10px;
153	  margin-top: -1px;
154	}
155	.race-thread::before {
156	  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 3px; transform: translateY(-50%);
157	  border-radius: 2px;
158	  background: repeating-linear-gradient(90deg, #f6d888 0 5px, #c48a2c 5px 7px);
159	  box-shadow: 0 0 0 1px rgba(255, 248, 228, .85), 0 1px 3px rgba(60, 25, 10, .5);
160	}
161	.race-thread::after {
162	  content: ""; position: absolute; right: -4px; top: 50%; width: 8px; height: 8px; transform: translateY(-50%) rotate(45deg);
163	  background: var(--gold); border: 1.5px solid #fff3d2; border-radius: 2px;
164	}
165	.race-thread .bead {
166	  position: absolute; top: 50%; left: 0; width: 10px; height: 10px; margin: -5px 0 0 -5px;
167	  border-radius: 50%; border: 1.5px solid #fff6df;
168	  box-shadow: 0 1px 2px rgba(50, 20, 10, .55);
169	  will-change: transform;
170	}
171	.race-thread .bead.purl { background: radial-gradient(circle at 35% 35%, #ff8d99, #e0344f 70%); z-index: 2; }
172	.race-thread .bead.loop { background: radial-gradient(circle at 35% 35%, #6fe0e2, #0b97a3 70%); width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; }
173	
174	.hud-hint {
175	  margin-top: max(2px, calc(var(--k) * 6px));
176	  max-width: calc(100% - 4 * var(--edge));
177	  padding: .45em 1em;
178	  border-radius: 1.2em;
179	  background: linear-gradient(#fff8e8, #f6e3c4);
180	  border: 1.5px solid #fff6df;
181	  box-shadow: 0 0 0 1px #c7a480 inset, 0 2px 6px rgba(60, 25, 10, .35);
182	  color: var(--brown);
183	  font-size: max(11px, calc(var(--k) * 21px));
184	  font-weight: 700;
185	  text-align: center;
186	  line-height: 1.25;
187	  animation: msgIn .3s ease-out;
188	}
189	
190	/* Results (approved 07): LEVEL 1 COMPLETE with flower ends, true ranks, times. */
191	.hud-results { display: flex; flex-direction: column; align-items: center; gap: var(--gap); }
192	.result-title {
193	  position: relative;
194	  font-size: max(15px, calc(var(--k) * 34px));
195	  min-width: max(13em, calc(var(--k) * 450px));
196	  padding: 0 1.9em;
197	  letter-spacing: .03em;
198	}
199	.result-title .orn { position: absolute; top: 50%; width: 1.75em; height: 1.75em; transform: translateY(-50%); }
200	.result-title .orn.l { left: -.55em; } .result-title .orn.r { right: -.55em; }
201	.result-ranks, .result-times { font-size: max(11.5px, calc(var(--k) * 22px)); min-width: max(14em, calc(var(--k) * 300px)); padding: 0 1.4em; gap: .45em; }
202	.result-times { font-size: max(10.5px, calc(var(--k) * 19px)); font-weight: 700; }
203	.result-ranks .p, .result-times .p { color: var(--coral); }
204	.result-ranks .l, .result-times .l { color: var(--teal); }
205	.result-ranks .dot, .result-times .dot { color: var(--brown); opacity: .75; }
206	.result-wait {
207	  font-size: max(11px, calc(var(--k) * 21px)); font-weight: 800; color: #fff8e5;
208	  padding: .3em .9em; border-radius: 1em;
209	  background: rgba(0, 105, 118, .82);
210	  box-shadow: 0 0 0 1.5px #83dfd1 inset, 0 2px 6px rgba(0, 40, 45, .4);
211	}
212	.result-wait .dots i { font-style: normal; animation: blink 1.2s infinite; }
213	.result-wait .dots i:nth-child(2) { animation-delay: .2s; } .result-wait .dots i:nth-child(3) { animation-delay: .4s; }
214	@keyframes blink { 0%, 100% { opacity: .2; } 40% { opacity: 1; } }
215	
216	/* Round stitched pause button, top-right (≥ 44 px). */
217	.btn-pause {
218	  position: absolute; z-index: 30;
219	  top: max(4px, calc(var(--k) * 40px));
220	  right: max(4px, calc(var(--k) * 22px));
221	  width: max(44px, calc(var(--k) * 74px)); height: max(44px, calc(var(--k) * 74px));
222	  padding: 0; border: 0; border-radius: 50%;
223	  background: url("assets/ui/pause.webp") center / 100% 100% no-repeat;
224	  filter: drop-shadow(0 2px 3px rgba(60, 25, 10, .45));
225	  cursor: pointer; touch-action: manipulation;
226	}
227	.btn-pause:active { transform: scale(.93); }
228	#game.no-logo .btn-pause { top: max(4px, calc(var(--k) * 14px)); }
229	
230	/* ---------- Buttons ---------- */
231	.btn-teal, .btn-cream {
232	  position: relative;
233	  display: flex; align-items: center; justify-content: center;
234	  min-height: 48px; min-width: 44px;
235	  border: 0 solid transparent;
236	  border-image-source: url("assets/ui/pill.webp");
237	  border-image-slice: 96 100 fill;
238	  border-image-repeat: stretch;
239	  background: none;
240	  font-weight: 900; letter-spacing: .04em;
241	  cursor: pointer; touch-action: manipulation;
242	  filter: drop-shadow(0 3px 4px rgba(60, 25, 10, .42));
243	}
244	.btn-teal { --bh: 52px; height: var(--bh); border-image-width: calc(var(--bh) / 2) calc(var(--bh) * .53); padding: 0; }
245	.btn-teal .face {
246	  position: absolute; inset: 15% 4.5% 17% 4.5%;
247	  display: flex; align-items: center; justify-content: center;
248	  border-radius: 999px;
249	  background: linear-gradient(180deg, #19b8bd 0%, var(--teal-bright) 35%, var(--teal-deep) 100%);
250	  box-shadow: inset 0 0 0 2px #83dfd1, inset 0 2px 0 rgba(255, 255, 255, .35), inset 0 -3px 4px rgba(0, 60, 70, .35);
251	  color: #fff8e5;
252	  font-size: 1.12em;
253	  text-shadow: 0 2px 0 rgba(0, 70, 80, .55);
254	}
255	.btn-cream { --bh: 48px; height: var(--bh); border-image-width: calc(var(--bh) / 2) calc(var(--bh) * .53); padding: 0 1.6em; color: var(--brown); font-size: 1em; }
256	.btn-teal:active, .btn-cream:active { transform: translateY(1px) scale(.98); }
257	.btn-teal:focus-visible, .btn-cream:focus-visible, .btn-pause:focus-visible, .btn-cashout:focus-visible { outline: 3px solid #ffd45c; outline-offset: 3px; }
258	.btn-wide { width: 100%; max-width: 290px; margin-left: auto; margin-right: auto; }
259	
260	/* PLAY AGAIN (approved 07), just above the rewards strip. */
261	.btn-play-again {
262	  --bh: max(52px, calc(var(--k) * 102px));
263	  position: absolute; z-index: 30; left: 50%; transform: translateX(-50%);
264	  bottom: calc(var(--rw-bottom) + var(--rw-h) + max(6px, calc(var(--k) * 10px)));
265	  width: max(232px, calc(var(--k) * 440px));
266	  font-size: max(17px, calc(var(--k) * 34px));
267	  animation: rise .45s cubic-bezier(.2, 1.4, .4, 1);
268	}
269	.btn-play-again:active { transform: translateX(-50%) translateY(1px) scale(.98); }
270	.btn-play-again .orn, .btn-teal .orn { position: absolute; top: 50%; width: 1.5em; height: 1.5em; transform: translateY(-50%); z-index: 2; }
271	.btn-play-again .orn.l { left: -.45em; } .btn-play-again .orn.r { right: -.45em; }
272	@keyframes rise { from { transform: translateX(-50%) translateY(30px); opacity: 0; } to { transform: translateX(-50%); opacity: 1; } }
273	
274	/* ---------- Saved rewards strip (placeholder only; locked cash out) ---------- */
275	.rewards {
276	  --ph: var(--rw-h);
277	  position: absolute; z-index: 20; left: 50%; transform: translateX(-50%);
278	  bottom: var(--rw-bottom);
279	  width: min(calc(100% - 2 * max(6px, calc(var(--k) * 30px))), max(292px, calc(var(--k) * 732px)));
280	  height: var(--rw-h);
281	  display: flex; align-items: center; gap: calc(var(--rw-h) * .2);
282	  padding: 0 calc(var(--rw-h) * .32) 0 calc(var(--rw-h) * .44);
283	  border: 0 solid transparent;
284	  border-image-source: url("assets/ui/pill.webp");
285	  border-image-slice: 96 100 fill;
286	  border-image-width: calc(var(--rw-h) / 2) calc(var(--rw-h) * .53);
287	  filter: drop-shadow(0 2px 4px rgba(60, 25, 10, .4));
288	  font-size: max(9px, calc(var(--k) * 17px));
289	  pointer-events: none;
290	}
291	.rw-label { color: var(--brown-2); font-weight: 900; letter-spacing: .01em; white-space: nowrap; }
292	.rw-bar {
293	  position: relative; flex: 1 1 calc(var(--k) * 172px); max-width: calc(var(--k) * 190px); min-width: 34px;
294	  height: calc(var(--rw-h) * .4); border-radius: 999px; background: #e8ceb2;
295	  box-shadow: inset 0 1px 2px rgba(120, 70, 30, .25);
296	}
297	.rw-bar i {
298	  position: absolute; left: 3%; top: 10%; bottom: 10%; width: 50%; border-radius: 999px;
299	  background: linear-gradient(180deg, #ff7c9d, var(--coral-bright) 55%, #d93466);
300	  box-shadow: inset 0 0 0 1.5px #ff9db0;
301	}
302	.rw-slot { flex: none; width: calc(var(--rw-h) * .5); height: calc(var(--rw-h) * .5); border-radius: 50%; background: #e8ceb2; box-shadow: inset 0 1px 2px rgba(120, 70, 30, .2); }
303	.btn-cashout {
304	  position: relative; flex: none; margin-left: auto;
305	  display: inline-flex; align-items: center; gap: .45em;
306	  height: calc(var(--rw-h) * .66); min-width: calc(var(--k) * 194px);
307	  padding: 0 1em 0 .8em;
308	  border-radius: 999px;
309	  border: 1.5px solid #cdc5b7;
310	  background: linear-gradient(180deg, #b3ac9f, #9a9387);
311	  color: #fffaf0; font-weight: 700; font-size: 1.05em; letter-spacing: .02em;
312	  white-space: nowrap;
313	  cursor: not-allowed; pointer-events: auto; touch-action: manipulation;
314	}
315	/* Enlarge the touch target to ≥ 44 px without changing the approved slim look. */
316	.btn-cashout::after { content: ""; position: absolute; left: -6px; right: -6px; top: 50%; height: 48px; transform: translateY(-50%); }
317	.btn-cashout .lock { width: 1.25em; height: 1.25em; color: #fffaf0; }
318	
319	.note {
320	  position: absolute; z-index: 40; right: max(8px, calc(var(--k) * 40px));
321	  bottom: calc(var(--rw-bottom) + var(--rw-h) + 8px);
322	  max-width: min(78%, 300px);
323	  padding: .7em 1em; border-radius: 14px;
324	  background: linear-gradient(#fff8e8, #f6e3c4);
325	  border: 1.5px solid #fff6df;
326	  box-shadow: 0 0 0 1px #c7a480 inset, 0 4px 10px rgba(50, 20, 10, .4);
327	  color: var(--brown); font-size: 12.5px; font-weight: 700; line-height: 1.35;
328	  animation: msgIn .25s ease-out;
329	  pointer-events: none;
330	}
331	.note::after { content: ""; position: absolute; right: 22%; bottom: -7px; width: 12px; height: 12px; background: #f6e3c4; transform: rotate(45deg); box-shadow: 1px 1px 0 #c7a480; }
332	
333	/* ---------- Countdown ---------- */
334	.countdown {
335	  position: absolute; z-index: 25; left: 0; right: 0; top: 36%;
336	  display: flex; justify-content: center; pointer-events: none;
337	}
338	.countdown span {
339	  display: block;
340	  font-size: max(72px, calc(var(--k) * 230px)); line-height: 1; font-weight: 900;
341	  color: #ff5a72;
342	  -webkit-text-stroke: max(4px, calc(var(--k) * 12px)) #fff3d6;
343	  paint-order: stroke fill;
344	  text-shadow: 0 calc(var(--k) * 10px) 0 rgba(120, 30, 40, .55), 0 0 30px rgba(255, 210, 120, .6);
345	  animation: count .9s ease-out both;
346	}
347	.countdown.go span { color: #12b2b8; text-shadow: 0 calc(var(--k) * 10px) 0 rgba(0, 80, 90, .55), 0 0 30px rgba(255, 230, 150, .7); }
348	@keyframes count { 0% { transform: scale(1.6); opacity: 0; } 18% { transform: scale(1); opacity: 1; } 78% { opacity: 1; } 100% { transform: scale(.85); opacity: .0; } }
349	
350	/* ---------- Overlays ---------- */
351	.overlay {
352	  position: absolute; inset: 0; z-index: 50;
353	  display: flex; align-items: center; justify-content: center;
354	  padding: max(10px, calc(var(--k) * 30px)) max(10px, calc(var(--k) * 30px));
355	  background: radial-gradient(ellipse at 50% 45%, rgba(45, 22, 12, .28), rgba(28, 12, 6, .66));
356	  overflow-y: auto; overscroll-behavior: contain;
357	  touch-action: pan-y;
358	  animation: fade .25s ease-out;
359	}
360	@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
361	.card {
362	  position: relative;
363	  width: 100%; max-width: 360px; margin: auto;
364	  padding: 18px 18px 16px;
365	  border-radius: 26px;
366	  background: linear-gradient(180deg, #fff9ec, #f6e2c2);
367	  box-shadow: 0 0 0 3px #fff6df, 0 0 0 4.5px #d7b48b, 0 14px 34px rgba(30, 10, 4, .55);
368	  color: var(--brown);
369	  text-align: center;
370	  font-size: 14px;
371	}
372	.card::before {
373	  content: ""; position: absolute; inset: 7px; border-radius: 20px;
374	  border: 2px dashed rgba(214, 162, 74, .85);
375	  pointer-events: none;
376	}
377	.card > * { position: relative; }
378	.ov-logo { display: block; width: 86%; max-width: 300px; height: auto; margin: -6px auto 4px; filter: drop-shadow(0 4px 5px rgba(60, 25, 10, .35)); }
379	.title-pill { font-size: 16px; margin: 2px auto 8px; padding: 0 1.4em; }
380	.card .sub { margin: 4px 6px 14px; font-size: 14px; line-height: 1.4; font-weight: 600; color: #6b3a20; }
381	.card .fine { margin: 10px 4px 0; font-size: 11.5px; line-height: 1.35; color: #8a5a3a; font-weight: 600; }
382	.card .btn-wide + .btn-wide { margin-top: 10px; }
